package com.ruoyi.framework.audit;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;import java.time.*;import java.nio.file.*;import com.alibaba.fastjson2.JSON;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.SimpleTransactionStatus;
class AuditRetentionProgressTest{
 @TempDir Path root;
 @Test void runtimeCleanupResumesAfter1000AndOnlyFinishesAllStages(){JdbcTemplate j=mock(JdbcTemplate.class);var manager=mock(PlatformTransactionManager.class);when(manager.getTransaction(any())).thenAnswer(a->new SimpleTransactionStatus());var config=new HashMap<String,Object>(Map.of("cleanup_enabled",true,"operation_days",180,"login_days",180,"runtime_days",30,"archive_days",365));var state=new HashMap<String,Object>(Map.of("status","RUNNING","stage","RUNTIME","cutoffs_json",JSON.toJSONString(Map.of("RUNTIME","2026-09-14T00:00","OUTBOX","2026-10-07T00:00","ARCHIVE","2025-10-14T00:00"))));
 when(j.queryForMap(anyString())).thenAnswer(a->a.<String>getArgument(0).contains("audit_log_config")?config:Map.of());when(j.queryForMap(contains("WHERE business_date=?"),any(Object[].class))).thenAnswer(a->new HashMap<>(state));when(j.queryForList(contains("status IN"))).thenReturn(List.of(Map.of("business_date",LocalDate.of(2026,10,14))));
 when(j.update(anyString(),any(Object[].class))).thenAnswer(a->{String q=a.getArgument(0);Object[] values=(Object[])a.getRawArguments()[1];if(q.contains("SET stage=?")){state.put("stage",values[0]);state.put("status",values[1]);}return 1;});when(j.update(contains("DELETE FROM sys_runtime_log"),any(Object[].class))).thenReturn(1000,500,0);when(j.update(contains("DELETE FROM audit_outbox"),any(Object[].class))).thenReturn(0);
 var service=new AuditRetention(j,manager,root);var now=LocalDateTime.of(2026,10,14,12,0);service.runAt(now);assertEquals("RUNTIME",state.get("stage"));assertEquals("RUNNING",state.get("status"));service.runAt(now);assertEquals("RUNTIME",state.get("stage"));service.runAt(now);assertEquals("OUTBOX",state.get("stage"));service.runAt(now);assertEquals("ARCHIVE",state.get("stage"));assertEquals("RUNNING",state.get("status"));service.runAt(now);assertEquals("DONE",state.get("stage"));assertEquals("SUCCESS",state.get("status"));verify(j,times(3)).update(contains("DELETE FROM sys_runtime_log"),any(Object[].class));verify(j).update(contains("status='DELIVERED' AND delivered_time<?"),any(Object[].class));
 }
 @Test void disabledCleanupDoesNotDeleteOrWriteProgress(){JdbcTemplate j=mock(JdbcTemplate.class);var manager=mock(PlatformTransactionManager.class);when(manager.getTransaction(any())).thenAnswer(a->new SimpleTransactionStatus());when(j.queryForMap(anyString())).thenReturn(Map.of("cleanup_enabled",false));new AuditRetention(j,manager,root).runAt(LocalDateTime.of(2026,10,14,12,0));verify(j,never()).update(anyString(),any(Object[].class));}
}
